// Antes: uma função a validar, calcular e reportar ao mesmo tempo
function processarPedidoAntes(pedido) {
  if (!pedido.itens || pedido.itens.length === 0) {
    throw new Error("Pedido sem itens");
  }
  let total = 0;
  for (const item of pedido.itens) {
    total += item.preco * item.quantidade;
  }
  total = total * 1.23;
  if (total > 100) {
    total = total - 10;
  }
  console.log(`A guardar pedido no valor de ${total}`);
  return total;
}

// Depois: cada função tem uma única responsabilidade
function validarPedido(pedido) {
  if (!pedido.itens || pedido.itens.length === 0) {
    throw new Error("Pedido sem itens");
  }
}

function calcularSubtotal(itens) {
  return itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0);
}

const TAXA_IVA = 0.23;
const DESCONTO_ACIMA_DE_100 = 10;

function aplicarImpostoEDesconto(subtotal) {
  const comImposto = subtotal * (1 + TAXA_IVA);
  return comImposto > 100 ? comImposto - DESCONTO_ACIMA_DE_100 : comImposto;
}

function processarPedido(pedido) {
  validarPedido(pedido);
  const subtotal = calcularSubtotal(pedido.itens);
  return aplicarImpostoEDesconto(subtotal);
}

// Evitar: estado global e números mágicos
