function filtrarProdutosAcimaDoPreco(produtos, precoMinimo) {
  const produtosFiltrados = [];
  for (const produto of produtos) {
    if (produto.preco >= precoMinimo) {
      produtosFiltrados.push(produto);
    }
  }
  return produtosFiltrados;
}

exercises.statement:
A função abaixo recebe um array de encomendas (cada uma com itens, cada item com preco e quantidade) e faz três coisas ao mesmo tempo, valida os dados, calcula o total com imposto e portes, e regista o resultado na consola. Usa também dois números mágicos (1.23 para o imposto e 50 para o limite de envio grátis):

function processar(encomendas) {
  let totalGeral = 0;
  for (const enc of encomendas) {
    if (!enc.itens || enc.itens.length === 0) {
      throw new Error('Encomenda vazia');
    }
    let subtotal = 0;
    for (const it of enc.itens) {
      subtotal += it.preco * it.quantidade;
    }
    subtotal = subtotal * 1.23;
    if (subtotal < 50) {
      subtotal += 5;
    }
    console.log('Encomenda processada: ' + subtotal);
    totalGeral += subtotal;
  }
  return totalGeral;
}

Refatore este código em várias funções mais pequenas, cada uma com uma única responsabilidade (validar uma encomenda, calcular o subtotal, aplicar imposto e portes, e orquestrar o processo), e substitua os números mágicos por constantes nomeadas. A função final deve continuar a devolver o total geral de todas as encomendas e a fazer o mesmo console.log por encomenda.

exercises.solution_code:
const TAXA_IVA = 0.23;
const VALOR_MINIMO_PARA_ENVIO_GRATIS = 50;
const CUSTO_DE_ENVIO = 5;

function validarEncomenda(encomenda) {
  if (!encomenda.itens || encomenda.itens.length === 0) {
    throw new Error("Encomenda vazia");
  }
}

function calcularSubtotal(itens) {
  return itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0);
}

function aplicarImpostoEPortes(subtotal) {
  const comImposto = subtotal * (1 + TAXA_IVA);
  return comImposto < VALOR_MINIMO_PARA_ENVIO_GRATIS
    ? comImposto + CUSTO_DE_ENVIO
    : comImposto;
}

function processarEncomendas(encomendas) {
  let totalGeral = 0;
  for (const encomenda of encomendas) {
    validarEncomenda(encomenda);
    const subtotal = calcularSubtotal(encomenda.itens);
    const totalComEncargos = aplicarImpostoEPortes(subtotal);
    console.log(`Encomenda processada: ${totalComEncargos}`);
    totalGeral += totalComEncargos;
  }
  return totalGeral;
}

exercises.statement:
O código abaixo tem vários cheiros de código, aninhamento profundo de condicionais, mutação do array recebido como argumento, um parâmetro booleano que altera o comportamento da função de forma pouco clara, comparação com == em vez de ===, e um comentário que apenas repete o que o código já diz:

// aplica desconto aos itens, opcionalmente também remove os esgotados
function processarItens(itens, remover) {
  if (remover) {
    // percorre o array e remove itens esgotados
    for (let i = itens.length - 1; i >= 0; i--) {
      if (itens[i].stock == 0) {
        itens.splice(i, 1);
      }
    }
  }
  for (const item of itens) {
    if (item.categoria === 'promocao') {
      if (item.stock > 0) {
        item.preco = item.preco * 0.9;
      }
    }
  }
  return itens;
}

Refatore esta função para: (1) nunca mutar o array nem os objetos recebidos como argumento, devolvendo sempre uma nova estrutura, (2) substituir o parâmetro booleano remover por duas funções distintas e bem nomeadas em vez de uma única função com comportamento condicional, (3) reduzir o aninhamento de condicionais usando guard clauses, (4) usar === em vez de ==, e (5) remover o comentário redundante, mantendo comentários apenas se explicarem algo que o código não torna óbvio.

