const DESCONTO_PROMOCAO = 0.9;

function removerItensEsgotados(itens) {
  return itens.filter((item) => item.stock > 0);
}

function aplicarDescontoPromocional(itens) {
  return itens.map((item) => {
    if (item.categoria !== "promocao" || item.stock <= 0) {
      return item;
    }
    return { ...item, preco: item.preco * DESCONTO_PROMOCAO };
  });
}

exercises.statement:
O módulo seguinte implementa um carrinho de compras muito simples, mas acumula vários problemas típicos: uma variável global carrinho que qualquer código pode alterar diretamente, nomes que não revelam intenção, números mágicos sem explicação, e uma função add que faz duas coisas ao mesmo tempo (adicionar o item e calcular o total):

let carrinho = [];
const IMPOSTO = 0.23;

function add(p, q) {
  carrinho.push({ p: p, q: q });
  let t = 0;
  for (let i = 0; i < carrinho.length; i++) {
    t = t + carrinho[i].p * carrinho[i].q;
  }
  if (t > 100) {
    t = t - t * 0.1;
  }
  t = t * IMPOSTO + t;
  return t;
}

Reescreva este módulo aplicando as práticas desta unidade: elimine a variável global encapsulando o estado do carrinho (por exemplo com uma closure que devolve funções para adicionar itens e obter o total), escolha nomes que revelem intenção em todos os identificadores, substitua os números mágicos por constantes nomeadas (limiar de desconto, percentagem de desconto e taxa de imposto), e separe claramente a responsabilidade de adicionar um item da responsabilidade de calcular o total. Só deve existir um comentário se explicar uma regra de negócio, nunca para repetir o que o código já diz.

