const LIMIAR_DESCONTO = 100;
const PERCENTAGEM_DESCONTO = 0.1;
const TAXA_IVA = 0.23;

function calcularTotalComEncargos(itens) {
  const subtotal = itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0);
  // Regra de negócio: compras acima do limiar têm 10% de desconto antes do IVA
  const subtotalComDesconto =
    subtotal > LIMIAR_DESCONTO ? subtotal - subtotal * PERCENTAGEM_DESCONTO : subtotal;
  return subtotalComDesconto * (1 + TAXA_IVA);
}

function criarCarrinho() {
  let itens = [];

  function adicionarItem(preco, quantidade) {
    itens = [...itens, { preco, quantidade }];
    return calcularTotalComEncargos(itens);
  }

  function obterItens() {
    return [...itens];
  }

  return { adicionarItem, obterItens };
}

const carrinho = criarCarrinho();
carrinho.adicionarItem(30, 2);
carrinho.adicionarItem(50, 1);
